import{_ as a,o as s,c as i,a2 as n}from"./chunks/framework.mRCPFc5l.js";const k=JSON.parse('{"title":"RAG 检索增强生成","description":"用分块、嵌入、向量检索与重排序把私有知识接进 LLM，让回答有据可查、可追溯，并理解 RAG 与微调的选择。","frontmatter":{"title":"RAG 检索增强生成","description":"用分块、嵌入、向量检索与重排序把私有知识接进 LLM，让回答有据可查、可追溯，并理解 RAG 与微调的选择。"},"headers":[],"relativePath":"ai/rag.md","filePath":"ai/rag.md","lastUpdated":1786263069000}'),e={name:"ai/rag.md"};function l(p,t,o,h,d,r){return s(),i("div",null,[...t[0]||(t[0]=[n(`<h1 id="rag-检索增强生成" tabindex="-1">RAG 检索增强生成 <a class="header-anchor" href="#rag-检索增强生成" aria-label="Permalink to &quot;RAG 检索增强生成&quot;">​</a></h1><p>LLM 的知识来自训练数据，它不知道你的内部文档、最新的产品手册、昨天才发布的政策。RAG（Retrieval-Augmented Generation，检索增强生成）解决的就是这个问题：在生成回答前，先从你的知识库里检索出相关片段，塞进上下文，让模型&quot;看着资料&quot;回答，而不是凭记忆瞎编。它的价值不只是减少幻觉，更在于让回答有据可查、可追溯、可更新。</p><h2 id="为什么需要外挂知识" tabindex="-1">为什么需要外挂知识 <a class="header-anchor" href="#为什么需要外挂知识" aria-label="Permalink to &quot;为什么需要外挂知识&quot;">​</a></h2><p>把知识&quot;放进模型&quot;有两条路：微调，或检索。微调把知识写进权重，更新一次要重新训练，成本高、周期长，而且模型仍可能在细节上出错，也无法告诉你&quot;这条答案出自哪份文档&quot;。检索则是把知识放在模型之外，每次回答时动态取用：</p><table tabindex="0"><thead><tr><th>方式</th><th>知识在哪</th><th>更新成本</th><th>可追溯</th></tr></thead><tbody><tr><td>纯模型</td><td>权重里</td><td>高（重新训练）</td><td>否</td></tr><tr><td>微调</td><td>权重里</td><td>中（需训练）</td><td>否</td></tr><tr><td>RAG</td><td>外部库</td><td>低（增删文档）</td><td>是</td></tr></tbody></table><p>对于&quot;知识经常变&quot;&quot;需要给出出处&quot;&quot;需要精确引用原文&quot;的场景，RAG 几乎总是更合适。微调更适合改变模型的风格、语气、领域术语习惯，而不是灌入具体事实。</p><h2 id="rag-的基本流程" tabindex="-1">RAG 的基本流程 <a class="header-anchor" href="#rag-的基本流程" aria-label="Permalink to &quot;RAG 的基本流程&quot;">​</a></h2><p>一次 RAG 问答由四个阶段组成：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>用户提问</span></span>
<span class="line"><span>  → 把问题转成向量</span></span>
<span class="line"><span>  → 在知识库向量索引里检索最相关的片段</span></span>
<span class="line"><span>  → 把片段和问题一起喂给模型</span></span>
<span class="line"><span>  → 模型基于片段生成回答</span></span></code></pre></div><p>关键在于中间两步：怎么把文档切成片段（分块），怎么找到相关片段（检索）。这两步的质量，直接决定最终回答的质量——检索阶段拿错了片段，再强的模型也只能基于错资料作答。</p><h2 id="分块策略" tabindex="-1">分块策略 <a class="header-anchor" href="#分块策略" aria-label="Permalink to &quot;分块策略&quot;">​</a></h2><p>知识库里的长文档不能整篇塞进上下文，必须切成片段（chunk）。分块粒度是个权衡：</p><table tabindex="0"><thead><tr><th>粒度</th><th>优点</th><th>缺点</th></tr></thead><tbody><tr><td>太小（单句）</td><td>检索精准</td><td>丢失上下文，片段孤立难理解</td></tr><tr><td>太大（整章）</td><td>上下文完整</td><td>噪音多、相关性被稀释、费 Token</td></tr><tr><td>适中（一段）</td><td>平衡</td><td>需要重叠避免切断语义</td></tr></tbody></table><p>实践里常用的做法是按固定长度切，并让相邻块有重叠（overlap），保证一个完整语义不会正好被切两半。更精细的做法是按文档结构切（标题、段落、列表项），保留语义边界。分块没有万能最优解，要结合自己的文档结构试验。</p><h2 id="嵌入与向量检索" tabindex="-1">嵌入与向量检索 <a class="header-anchor" href="#嵌入与向量检索" aria-label="Permalink to &quot;嵌入与向量检索&quot;">​</a></h2><p>嵌入（embedding）把一段文本映射成一个高维向量，语义相近的文本向量也相近。检索时，把用户问题也转成向量，在向量库里找距离最近的几个片段。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>问题: &quot;怎么重置密码&quot;</span></span>
<span class="line"><span>  → 向量 [0.12, -0.04, ...]</span></span>
<span class="line"><span>  → 最近邻: &quot;忘记密码时，点击登录页的&#39;忘记密码&#39;重置...&quot; (相似度 0.91)</span></span></code></pre></div><p>要点：</p><ul><li><strong>嵌入模型决定语义匹配质量</strong>：好的嵌入模型能识别&quot;重置密码&quot;和&quot;找回密码&quot;是同一意思，差的只会匹配字面。选嵌入模型要用自己的语料测，而不是看榜单。</li><li><strong>向量库负责高效近邻搜索</strong>：常用方案都支持大规模近似检索，工程上不必自己实现。</li><li><strong>关键词检索仍有价值</strong>：向量检索擅长语义相似，但对专有名词、编号、代码标识符，关键词检索（如 BM25）往往更准。两者融合（hybrid）是生产环境的常见做法。</li></ul><h2 id="重排序" tabindex="-1">重排序 <a class="header-anchor" href="#重排序" aria-label="Permalink to &quot;重排序&quot;">​</a></h2><p>向量检索速度快但不够精细，往往召回一批&quot;大致相关&quot;的片段。重排序（rerank）用一个更精细但更慢的模型，对召回的这批片段重新打分，把最相关的排到前面，再截取 top-K 喂给模型。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>检索召回 50 个片段（快，粗）</span></span>
<span class="line"><span>  → 重排序模型精细打分（慢，准）</span></span>
<span class="line"><span>  → 取 top 5 塞进上下文</span></span></code></pre></div><p>这一步能显著提升最终质量，因为它过滤掉了&quot;向量距离近但实际不相关&quot;的噪音，让模型拿到的是真正有用的片段。</p><h2 id="引用与可追溯性" tabindex="-1">引用与可追溯性 <a class="header-anchor" href="#引用与可追溯性" aria-label="Permalink to &quot;引用与可追溯性&quot;">​</a></h2><p>RAG 相比纯模型的最大优势是&quot;可追溯&quot;：回答里每一条论断都能指向具体的源文档片段。实现上，把检索到的片段带上网元信息（文档名、章节、位置），要求模型在回答时标注引用：</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;answer&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;重置密码需点击登录页的&#39;忘记密码&#39;。&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;citations&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    { </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;doc&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;用户手册&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;section&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;3.2 账号安全&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;snippet&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;忘记密码时，点击...&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  ]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>引用不只是为了好看——它是用户校验答案、建立信任的依据，也是定位检索错误的抓手。如果模型答错了，顺着引用能快速看出是&quot;检索没找到对的片段&quot;还是&quot;检索对了但模型理解错了&quot;，从而知道该优化哪一环。</p><h2 id="rag-还是微调" tabindex="-1">RAG 还是微调 <a class="header-anchor" href="#rag-还是微调" aria-label="Permalink to &quot;RAG 还是微调&quot;">​</a></h2><p>常见的误区是&quot;二选一&quot;。实际上两者解决不同问题：</p><ul><li><strong>知识更新、事实问答、需要引用</strong> → RAG。知识在外部，改文档即生效。</li><li><strong>改变模型行为风格、领域术语、固定格式输出</strong> → 微调。</li><li><strong>两者可以叠加</strong>：微调让模型更懂领域表达方式，RAG 提供具体事实。</li></ul><p>先做 RAG。多数&quot;模型不懂我的业务&quot;的问题，根源是模型没看到你的资料，而不是它没学会你的领域风格。RAG 见效快、成本低、可追溯，应当作为首选；微调作为 RAG 解决不了行为层面问题时的补充。</p><h2 id="务实的清单" tabindex="-1">务实的清单 <a class="header-anchor" href="#务实的清单" aria-label="Permalink to &quot;务实的清单&quot;">​</a></h2><ul><li>检索质量测过吗？拿真实问题测召回，而不是凭感觉。</li><li>分块粒度是否贴合文档结构，有没有重叠？</li><li>是否定期评估嵌入模型和重排序在自己的语料上的表现？</li><li>回答是否带引用，能不能从答案追回源片段？</li><li>文档更新后，索引是否同步刷新，有没有过期知识残留？</li></ul><p>RAG 的本质，是把&quot;知识&quot;从模型权重里拿出来，放进一个你能管理、能更新、能审计的外部系统。把检索这一环做扎实，上层用哪个模型、怎么写 prompt，都是在可靠地基上盖楼。</p>`,34)])])}const c=a(e,[["render",l]]);export{k as __pageData,c as default};
